use std::{
    net::SocketAddr,
    path::PathBuf,
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    time::Duration,
};

use tiny_http::Server as TinyServer;

use crate::{
    HttpError,
    routes::{Backend, Routes},
    static_files::StaticRoot,
};

/// What the server reviews.
#[derive(Clone, Debug)]
pub enum Mode {
    /// One prepared workspace holding `.gewu/review-input.json` and
    /// `.gewu/review-spec.json`.
    Review { root: PathBuf },
    /// Every repository and review task under `home`, generated by agents
    /// that receive `gewu` as their harness binary.
    Workbench { home: PathBuf, gewu: PathBuf },
}

/// Options for [`Server::start`].
#[derive(Clone, Debug)]
pub struct ServeOptions {
    pub mode: Mode,
    pub static_dir: PathBuf,
    /// Use `0` to let the OS pick an ephemeral port.
    pub port: u16,
}

/// HTTP server for the app protocol and static UI assets. Each request is
/// answered on a thread of its own, so a slow `gh` call does not stall polls.
pub struct Server {
    inner: TinyServer,
    routes: Arc<Routes>,
    stop: Arc<AtomicBool>,
}

impl Server {
    /// Open the backend, bind `127.0.0.1:<port>`, and return a ready server.
    /// Call [`Server::run`] to handle requests until [`Server::stop`] is called
    /// or the process exits.
    pub fn start(options: ServeOptions) -> Result<Self, HttpError> {
        let backend = Backend::open(options.mode)?;
        let static_files = StaticRoot::new(options.static_dir)?;
        let addr = format!("127.0.0.1:{}", options.port);
        let inner = TinyServer::http(&addr).map_err(HttpError::Bind)?;
        Ok(Self {
            inner,
            routes: Arc::new(Routes::new(backend, static_files)),
            stop: Arc::new(AtomicBool::new(false)),
        })
    }

    /// Address the server is listening on (useful when `port` was `0`).
    #[must_use]
    pub fn local_addr(&self) -> SocketAddr {
        self.inner
            .server_addr()
            .to_ip()
            .expect("gewu-http binds IPv4 only")
    }

    /// Signal [`Server::run`] to return after the current wait times out.
    pub fn stop(&self) {
        self.stop.store(true, Ordering::SeqCst);
        self.inner.unblock();
    }

    /// Cloneable handle that can stop a running server from another thread.
    #[must_use]
    pub fn stopper(&self) -> Arc<AtomicBool> {
        Arc::clone(&self.stop)
    }

    /// Serve requests until [`Server::stop`] is called.
    pub fn run(&self) -> Result<(), HttpError> {
        while !self.stop.load(Ordering::SeqCst) {
            match self.inner.recv_timeout(Duration::from_millis(100)) {
                Ok(Some(request)) => {
                    let routes = Arc::clone(&self.routes);
                    std::thread::Builder::new()
                        .name("gewu-http".into())
                        .spawn(move || routes.handle(request))?;
                }
                Ok(None) => {}
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {}
                Err(error) if error.kind() == std::io::ErrorKind::TimedOut => {}
                Err(error) => return Err(HttpError::Io(error)),
            }
        }
        Ok(())
    }

    /// Bind and serve until the process is stopped.
    pub fn serve(options: ServeOptions) -> Result<(), HttpError> {
        Self::start(options)?.run()
    }
}

impl ServeOptions {
    /// Serve one prepared review workspace.
    #[must_use]
    pub fn new(root: impl Into<PathBuf>, static_dir: impl Into<PathBuf>, port: u16) -> Self {
        Self {
            mode: Mode::Review { root: root.into() },
            static_dir: static_dir.into(),
            port,
        }
    }

    /// Serve the workbench kept under `home`.
    #[must_use]
    pub fn workbench(
        home: impl Into<PathBuf>,
        gewu: impl Into<PathBuf>,
        static_dir: impl Into<PathBuf>,
        port: u16,
    ) -> Self {
        Self {
            mode: Mode::Workbench {
                home: home.into(),
                gewu: gewu.into(),
            },
            static_dir: static_dir.into(),
            port,
        }
    }
}
